import TextInput from "@marko-ui/shadcn/ui/input/input.marko";
import Label from "@marko-ui/shadcn/ui/label/label.marko";

<div class="grid w-full max-w-xs items-center gap-1.5">
  <Label for="email">Email</Label>
  <TextInput type="email" id="email" placeholder="Email"/>
</div>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";

<Field>
  <FieldLabel for="input-field-username">Username</FieldLabel>
  <TextInput id="input-field-username" type="text" placeholder="Enter your username"/>
  <FieldDescription>Choose a unique username for your account.</FieldDescription>
</Field>

import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";

<Field orientation="horizontal">
  <TextInput type="search" placeholder="Search..."/>
  <Button type="button">Search</Button>
</Field>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";

<Field>
  <FieldLabel for="input-required">
    Required Field <span class="text-destructive">*</span>
  </FieldLabel>
  <TextInput id="input-required" placeholder="This field is required" required/>
  <FieldDescription>This field must be filled out.</FieldDescription>
</Field>

import Badge from "@marko-ui/shadcn/ui/badge/badge.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";

<Field>
  <FieldLabel for="input-badge">
    Webhook URL
    <Badge variant="secondary" class="ml-auto">Beta</Badge>
  </FieldLabel>
  <TextInput id="input-badge" type="url" placeholder="https://api.example.com/webhook"/>
</Field>

import Button from "@marko-ui/shadcn/ui/button/button.marko";
import ButtonGroup from "@marko-ui/shadcn/ui/button-group/button-group.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";

<Field>
  <FieldLabel for="input-button-group">Search</FieldLabel>
  <ButtonGroup>
    <TextInput id="input-button-group" placeholder="Type to search..."/>
    <Button type="button" variant="outline">Search</Button>
  </ButtonGroup>
</Field>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";

<Field dir="rtl">
  <FieldLabel for="input-rtl-api-key">مفتاح API</FieldLabel>
  <TextInput id="input-rtl-api-key" type="password" placeholder="sk-..." dir="rtl"/>
  <FieldDescription>مفتاح API الخاص بك مشفر ومخزن بأمان.</FieldDescription>
</Field>
